p='src/Storefront/Invoices/LedgerWriter.cs'
s=open(p).read()
old=s[s.index('        // Write as we go'):s.index('        return count;')]
new='''        // Write as we go through one open stream: the month-end ledger never has to fit in memory,
        // and the file is opened once rather than once per invoice.
        using var writer = new StreamWriter(path, append: false);
        writer.WriteLine(Header);

        var count = 0;
        foreach (var invoice in invoices)
        {
            writer.WriteLine(Line(invoice));
            count++;
        }

'''
open(p,'w').write(s.replace(old,new))
EOF
